let rawData: any = "hello";
rawData.nonExistentMethod(); // 컴파일 통과, 런타임 크래시!

// 2. unknown: 안전한 Top Type (타입 좁히기 없이는 멤버 접근 불가)
let mystery: unknown = "Hello TypeScript";
// mystery.toUpperCase(); // 컴파일 에러! Object is of type 'unknown'.
if (typeof mystery === "string") {
    console.log(mystery.toUpperCase()); // 좁히기 후 안전하게 호출
}

// 3. void: 반환값이 없는 함수의 반환 타입
function logMessage(msg: string): void {
    console.log(`[INFO] ${msg}`);
}

// 4. never: 도달 불가능(Unreachable) 또는 항상 예외를 던지는 함수
function fail(message: string): never {
    throw new Error(message);
}

// never를 활용한 완전성(Exhaustiveness) 검증
type Role = "admin" | "user";
function checkRole(role: Role) {
    if (role === "admin") return "관리자";
    if (role === "user") return "일반회원";
    const _exhaustiveCheck: never = role; // 새 역할 추가 시 컴파일 타임 경고 유도
    return _exhaustiveCheck;
}

