interface UserEvents {
    click: (x: number, y: number) => void;
    hover: (element: string) => void;
    scroll: (offset: number) => void;
    metadata: string; // 함수가 아닌 일반 프로퍼티
}

// 1. 키 이름 재매핑: 'click' -> 'onClick'
type EventHandlerNames<T> = {
    [K in keyof T as K extends string ? `on${Capitalize<K>}` : never]: T[K];
};
type Handlers = EventHandlerNames<UserEvents>;
// 결과: { onClick: ..., onHover: ..., onScroll: ..., onMetadata: string }

// 2. 값 타입 기반 키 필터링 (함수만 유지하고 일반 프로퍼티 제거)
type MethodsOnly<T> = {
    [K in keyof T as T[K] extends (...args: any[]) => any ? K : never]: T[K];
};
type EventMethods = MethodsOnly<UserEvents>;
// 결과: click, hover, scroll만 남고 metadata는 제거됨!

// 1. 기본 조건부 타입 및 분산 조건부 타입(Distributive Conditional Types)
type NonNull<T> = T extends null | undefined ? never : T;
type Cleaned = NonNull<string | number | null>; // string | number (null 제거됨)

// 2. infer 키워드를 통한 함수의 반환 타입 추출 (ReturnType 직접 구현)
type CustomReturnType<T> = T extends (...args: any[]) => infer R ? R : never;

function fetchAccount() {
    return { id: 777, name: "VIP Customer", balance: 1500000 };
}
type AccountData = CustomReturnType<typeof fetchAccount>;
// AccountData -> { id: number; name: string; balance: number }

// 3. 배열 원소 타입 언래핑
type ElementOf<T> = T extends (infer E)[] ? E : T;
type StringItem = ElementOf<string[]>; // string

// 1. 유니온 문자열 결합을 통한 CSS 단위 및 이벤트 타입 생성
type Alignment = "top" | "bottom";
type Justification = "left" | "right";
type Position = `${Alignment}-${Justification}`;
// "top-left" | "top-right" | "bottom-left" | "bottom-right"

// 2. 게터/세터 메서드 이름 타입 동적 구성
type Prop = "name" | "age";
type GetterName<T extends string> = `get${Capitalize<T>}`;
type PropGetters = GetterName<Prop>; // "getName" | "getAge"

// 3. API 엔드포인트 URL 패턴 검증
type ApiEndpoint = `/api/v1/${string}`;
const validEndpoint: ApiEndpoint = "/api/v1/users";
// const invalidEndpoint: ApiEndpoint = "/v2/users"; // 컴파일 에러!

type RGB = [red: number, green: number, blue: number];
type Color = string | RGB;

type Palette = Record<"primary" | "secondary" | "accent", Color>;

// satisfies를 사용하여 Palette 규격을 만족하는지 확인하되, 각 프로퍼티의 구체적 타입을 유지
const theme = {
