// 1. 구체적 타입 보존: string 메서드를 바로 안전하게 호출 가능!
console.log(theme.primary.toUpperCase()); // theme.primary는 string으로 추론됨 (Color 유니온으로 넓혀지지 않음!)

// 2. 튜플 속성도 그대로 보존
console.log(theme.secondary[0]); // number로 안전하게 접근

// 3. 누락되거나 오탈자가 난 키는 엄격하게 검증 차단
// const badTheme = { primary: "#fff" } satisfies Palette; // 컴파일 에러! secondary, accent 누락

