grammar.example:
interface Cat {
    name: string;
    meow: () => void;
}
interface Dog {
    name: string;
    bark: () => void;
}
type Pet = Cat | Dog;

// 1. 사용자 정의 타입 가드 함수
function isDog(pet: Pet): pet is Dog {
    return (pet as Dog).bark !== undefined;
}

function playWithPet(pet: Pet) {
    if (isDog(pet)) {
        pet.bark(); // Dog 타입으로 좁혀짐
    } else {
        pet.meow(); // Cat 타입으로 좁혀짐
    }
}

// 2. Array.prototype.filter와 결합
const pets: Pet[] = [
    { name: "초코", bark: () => console.log("멍멍") },
    { name: "나비", meow: () => console.log("야옹") },
];
// isDog를 전달하면 dogs의 타입은 Dog[]로 정확히 추론됨
const dogs: Dog[] = pets.filter(isDog);

