grammar.example:
// 1. 조건 참 단언 함수
function assertCondition(expr: unknown, message: string): asserts expr {
    if (!expr) {
        throw new Error(`단언 실패: ${message}`);
    }
}

// 2. 타입 일치 단언 함수
function assertIsNumber(val: unknown): asserts val is number {
    if (typeof val !== "number") {
        throw new TypeError(`Expected number, got ${typeof val}`);
    }
}

function processValue(val: string | number | null) {
    assertCondition(val !== null, "값은 null일 수 없습니다.");
    // 이 시점 이후 val은 string | number로 좁혀짐

    assertIsNumber(val);
    // 이 시점 이후 val은 number로 완벽하게 좁혀짐 (if문 불필요!)
    console.log("제곱값:", val.toFixed(2));
}

