// 메서드 실행 시간 및 로그 데코레이터 (TS 5.0+ 표준)
function loggedMethod<This, Args extends any[], Return>(
    target: (this: This, ...args: Args) => Return,
    context: ClassMethodDecoratorContext<This, (this: This, ...args: Args) => Return>
) {
    const methodName = String(context.name);

    return function (this: This, ...args: Args): Return {
        console.log(`[CALL] ${methodName} 호출됨. 인자:`, args);
        const start = performance.now();
        const result = target.call(this, ...args);
        console.log(`[EXIT] ${methodName} 완료 (${(performance.now() - start).toFixed(2)}ms)`);
        return result;
    };
}

class DataService {
    @loggedMethod
    calculateStatistics(data: number[]): number {
        return data.reduce((acc, cur) => acc + cur, 0);
    }
}

const service = new DataService();
service.calculateStatistics([10, 20, 30, 40]);

