// 1. Symbol.dispose 인터페이스 구현
class TempDirectoryManager implements Disposable {
    constructor(public readonly dirPath: string) {
        console.log(`[ALLOC] 임시 디렉터리 생성: ${dirPath}`);
    }

    [Symbol.dispose]() {
        console.log(`[CLEANUP] 임시 디렉터리 자동 삭제 완료: ${this.dirPath}`);
    }
}

function processBatchFiles() {
    // using 키워드로 자원 바인딩 -> 함수 스코프 종료 시 [Symbol.dispose]() 자동 호출
    using tempDir = new TempDirectoryManager("/tmp/batch-work");
    console.log("작업 진행 중...");
    // 스코프가 끝나거나 도중 예외가 발생해도 tempDir.[Symbol.dispose]()가 즉시 실행됨!
}
processBatchFiles();

// 2. 비동기 리소스 관리 (await using & Symbol.asyncDispose)
